describe('Breadcrumbs Navigation', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should display breadcrumbs showing current location in site hierarchy', () => {
    cy.visit('/products/electronics/laptops');

    cy.get('[data-testid="breadcrumbs"]').should('be.visible');

    cy.get('[data-testid="breadcrumbs"] li').should('have.length', 4);

    cy.get('[data-testid="breadcrumbs"] li').eq(0).should('contain', 'Home');
    cy.get('[data-testid="breadcrumbs"] li').eq(1).should('contain', 'Products');
    cy.get('[data-testid="breadcrumbs"] li').eq(2).should('contain', 'Electronics');
    cy.get('[data-testid="breadcrumbs"] li').eq(3).should('contain', 'Laptops');
  });

  it('should navigate to parent pages when clicking breadcrumb links', () => {
    cy.visit('/products/electronics/laptops/gaming');

    cy.get('[data-testid="breadcrumbs"] li').eq(2).find('a').click();

    cy.url().should('include', '/products/electronics');
    cy.get('[data-testid="breadcrumbs"] li').should('have.length', 3);
    cy.get('[data-testid="breadcrumbs"] li').eq(2).should('contain', 'Electronics');
  });

  it('should display only home breadcrumb on root page', () => {
    cy.visit('/');

    cy.get('[data-testid="breadcrumbs"]').should('be.visible');
    cy.get('[data-testid="breadcrumbs"] li').should('have.length', 1);
    cy.get('[data-testid="breadcrumbs"] li').eq(0).should('contain', 'Home');
  });

  it('should not have clickable link for current page breadcrumb', () => {
    cy.visit('/products/electronics/laptops');

    cy.get('[data-testid="breadcrumbs"] li').last().find('a').should('not.exist');
    cy.get('[data-testid="breadcrumbs"] li').last().should('have.attr', 'aria-current', 'page');
  });

  it('should handle deeply nested breadcrumb paths', () => {
    cy.visit('/products/electronics/laptops/gaming/high-performance/asus');

    cy.get('[data-testid="breadcrumbs"] li').should('have.length', 7);
    cy.get('[data-testid="breadcrumbs"] li').eq(0).should('contain', 'Home');
    cy.get('[data-testid="breadcrumbs"] li').eq(6).should('contain', 'Asus');
    cy.get('[data-testid="breadcrumbs"] li').eq(6).find('a').should('not.exist');
  });

  it('should update breadcrumbs when navigating between different sections', () => {
    cy.visit('/products/electronics/laptops');
    cy.get('[data-testid="breadcrumbs"] li').eq(2).should('contain', 'Electronics');

    cy.visit('/services/support/documentation');
    cy.get('[data-testid="breadcrumbs"] li').should('have.length', 4);
    cy.get('[data-testid="breadcrumbs"] li').eq(1).should('contain', 'Services');
    cy.get('[data-testid="breadcrumbs"] li').eq(2).should('contain', 'Support');
    cy.get('[data-testid="breadcrumbs"] li').eq(3).should('contain', 'Documentation');
  });

  it('should have proper accessibility attributes on breadcrumbs', () => {
    cy.visit('/products/electronics/laptops');

    cy.get('[data-testid="breadcrumbs"]').should('have.attr', 'role', 'navigation');
    cy.get('[data-testid="breadcrumbs"]').should('have.attr', 'aria-label');
    cy.get('[data-testid="breadcrumbs"] li').last().should('have.attr', 'aria-current', 'page');
  });
});
